from datetime import timedelta

from config import (
    DRY_RUN,
    INACTIVE_BILLING_STATUSES,
    INVESTIGATION_FIRE_TIMEOUT_HOURS,
    LAMBDA_SERVICES,
    STAGE,
)
from resources import Connection, function_to_resource_map
from utils.boto import (
    first_crawl_complete,
    get_agent_github_pat,
    get_connection_errors,
    get_connection_scheduler_rows,
    get_connections_row,
    get_open_sync_jobs,
    get_org_row_cached,
    record_event,
    scan_connection_rows,
    update_crawl_items,
    update_sync_job,
    write_pickle_to_s3,
)
from utils.celery import crawl_started
from utils.exceptions import PokedexException
from utils.github import close_investigation_pr, get_pr_merged_at
from utils.integrations import (
    get_integration_file,
    resolve_crawl_frequency,
    resolve_disabled_functions,
)
from utils.investigation import conclude_investigation
from utils.lambda_util import LambdaContextManager
from utils.linear import get_issue_state_type
from utils.logutil import getLogger
from utils.utils import dt_to_str, now, str_to_dt

logger = getLogger()


def maybe_release_investigation(schedule, connection_id, function_name):
    # a code-fix PR that merged but didn't clear staleness means the shipped fix
    # didn't work — release the pointer so the next dispatch re-investigates.
    investigation = schedule.get("last_investigation") or {}
    if investigation.get("status") != "open":
        return
    pr_url = investigation.get("pr_url")
    if not pr_url:
        if not investigation.get("linear_ticket_url"):
            maybe_release_dead_fire(
                schedule, connection_id, function_name, investigation
            )
            return
        # escalate/customer/vendor/infra investigations never had a PR — the only
        # signal a human resolved one is the ticket's own Linear state.
        maybe_release_resolved_ticket(
            schedule, connection_id, function_name, investigation
        )
        return
    if DRY_RUN:
        logger.info(
            f"Would check merged PR to release investigation for {connection_id}/{function_name}"
        )
        return
    try:
        gh_token = get_agent_github_pat()
        merged_at = get_pr_merged_at(pr_url, gh_token)
    except Exception as e:
        logger.warning(
            f"Failed to check PR {pr_url} for {connection_id}/{function_name}: {e}"
        )
        return
    if not merged_at:
        # the pr didn't ship, so the card is the only thing that says whether this
        # cluster was concluded (a sibling recovered, or a human closed it)
        maybe_release_resolved_ticket(
            schedule, connection_id, function_name, investigation
        )
        return
    release_dict: dict[str, object] = {}
    conclude_investigation(schedule, release_dict)
    update_crawl_items(connection_id, function_name, release_dict)
    logger.info(
        f"Released merged-but-stale investigation for {connection_id}/{function_name}"
    )


def maybe_release_dead_fire(schedule, connection_id, function_name, investigation):
    # a fired pointer with no card or PR long after the fire means the session died
    fired_at = investigation.get("fired_at")
    if not fired_at:
        return
    try:
        fired_dt = str_to_dt(fired_at)
    except ValueError:
        return
    if now() - fired_dt < timedelta(hours=INVESTIGATION_FIRE_TIMEOUT_HOURS):
        return
    if DRY_RUN:
        logger.info(
            f"Would release dead-fire investigation for {connection_id}/{function_name}"
        )
        return
    release_dict: dict[str, object] = {"last_investigation": None}
    update_crawl_items(connection_id, function_name, release_dict)
    logger.info(
        f"Released dead-fire investigation for {connection_id}/{function_name} (fired {fired_at}, no artifacts)"
    )


def maybe_release_resolved_ticket(
    schedule, connection_id, function_name, investigation
):
    linear_ticket_url = investigation.get("linear_ticket_url")
    if not linear_ticket_url:
        return
    if DRY_RUN:
        logger.info(
            f"Would check Linear state to release investigation for {connection_id}/{function_name}"
        )
        return
    try:
        state_type = get_issue_state_type(linear_ticket_url)
    except Exception as e:
        logger.warning(
            f"Failed to check Linear state {linear_ticket_url} for {connection_id}/{function_name}: {e}"
        )
        return
    if state_type not in ("completed", "canceled"):
        return
    # the re-fire opens its own pr, so don't leave this one open beside it;
    # keep the pointer while the close fails so the next sweep retries
    try:
        closed = close_investigation_pr(schedule)
    except Exception as e:
        logger.warning(
            f"Failed to close investigation PR for {connection_id}/{function_name}: {e}"
        )
        closed = False
    if not closed:
        return
    release_dict: dict[str, object] = {"last_investigation": None}
    update_crawl_items(connection_id, function_name, release_dict)
    logger.info(
        f"Released investigation for {connection_id}/{function_name} (ticket already resolved)"
    )


def check_sync_job_staleness(open_sync_jobs):
    page_token_threshold = timedelta(hours=3)
    max_lifetime_threshold = timedelta(days=1)

    for job in open_sync_jobs:
        job_id = job["id"]
        current_stale = job.get("stale", False)

        created_at_dt = str_to_dt(job["created_at"])

        last_page_token_update = job.get("last_page_token_update")
        if not last_page_token_update:
            is_stale = now() - created_at_dt > page_token_threshold
        else:
            is_stale = now() - str_to_dt(last_page_token_update) > page_token_threshold

        exceeded_max_lifetime = now() - created_at_dt > max_lifetime_threshold
        is_stale = is_stale or exceeded_max_lifetime

        if is_stale != current_stale:
            if not DRY_RUN:
                update_sync_job(job_id, {"stale": is_stale})


def build_stuck_webhook_resource(connection_id, function_name):
    # both the sync-job and schedule stuck webhooks need the connection and resource
    try:
        connection = get_connections_row(connection_id, ignore_deleted=True)
    except Exception as e:
        # an orphaned job (connection deleted) shouldn't crash the sweep.
        logger.warning(f"Connection {connection_id} not found, no stuck webhook: {e}")
        return None
    integration_name = connection["integration_name"]
    integration_type = connection["integration_type"]
    org_id = connection["org_id"]
    customer_id = connection["customer_id"]
    try:
        integration_file = get_integration_file(integration_name, integration_type)
    except PokedexException as e:
        if e.status_code == 404:
            logger.warning(
                f"Integration {integration_name} not found, no stuck webhook"
            )
            return None
        raise
    if function_name not in function_to_resource_map.get(integration_type, {}):
        logger.warning(f"Unknown function {function_name}, no stuck webhook")
        return None
    integration = integration_file.Integration(
        connection_id=connection_id,
        org_id=org_id,
        customer_id=customer_id,
    )
    resource = function_to_resource_map[integration_type][function_name](integration)
    return resource


def check_sync_job_stuckness(open_sync_jobs):
    page_token_threshold = timedelta(hours=12)
    for job in open_sync_jobs:
        job_id = job["id"]
        connection_id = job["connection_id"]
        function_name = job["function_name"]
        # fall back to created_at to catch jobs stuck before any page token update.
        last_progress = job.get("last_page_token_update") or job["created_at"]
        requested_start = job["requested_start_time"]
        requested_end = job["requested_end_time"]
        time_now = now()
        is_stuck = time_now - str_to_dt(last_progress) > page_token_threshold
        if not is_stuck:
            continue
        if DRY_RUN:
            continue
        resource = build_stuck_webhook_resource(connection_id, function_name)
        if not resource:
            # No resource found for job, cancel it
            update_sync_job(
                job_id, {"status": "cancelled", "cancelled_at": dt_to_str(now())}
            )
            continue
        stuck_str = dt_to_str(time_now)
        send_sync_stuck_webhook(
            job_id, resource, stuck_str, requested_start, requested_end
        )
        update_sync_job(job_id, {"status": "stuck"})
        resource.integration.record_event(
            "on_demand_sync_stuck",
            additional_fields={
                "function_name": function_name,
                "requested_start_time": requested_start,
                "requested_end_time": requested_end,
            },
        )


def send_sync_stuck_webhook(
    sync_job_id, resource, stuck, requested_start, requested_end
):
    if resource.suppress_webhooks():
        return
    sync_stuck_item = {
        "item": {
            "sync_job_id": sync_job_id,
            "connection_id": resource.integration.connection_id,
            "stuck_date": stuck,
            "requested_start_date": requested_start,
            "requested_end_date": requested_end,
            "resource": resource.name(),
        },
        "action": "sync-job-stuck",
    }
    connection_resource = Connection(resource.integration).trimmed()
    webhook_payload = {
        "resource": connection_resource,
        "data": [sync_stuck_item],
        "tracking_id": f"sync-{sync_job_id}",
    }
    write_pickle_to_s3("webhook", webhook_payload, source="stale-schedule-marker")


def send_schedule_stuck_webhook(resource, function_name, stuck, latest_data):
    if resource.suppress_webhooks():
        return
    schedule_stuck_item = {
        "item": {
            "connection_id": resource.integration.connection_id,
            "resource": resource.name(),
            "stuck_date": stuck,
            "latest_data": latest_data,
        },
        "action": "schedule-stuck",
    }
    connection_resource = Connection(resource.integration).trimmed()
    webhook_payload = {
        "resource": connection_resource,
        "data": [schedule_stuck_item],
        "tracking_id": f"schedule-stuck-{resource.integration.connection_id}-{function_name}",
    }
    write_pickle_to_s3("webhook", webhook_payload, source="stale-schedule-marker")


def check_schedule_stuckness(
    connection, schedules, active_syncs, disabled_functions, org_inactive
):
    # a crawl in progress whose page token hasn't moved in 12h has died mid-flight.
    # this tracks progress, not data freshness, so it's separate from the stale flag.
    page_token_threshold = timedelta(hours=12)
    connection_id = connection["id"]
    deleted = connection.get("deleted", False)
    for schedule in schedules:
        function_name = schedule["function_name"]
        if (connection_id, function_name) in active_syncs:
            continue
        marked_stuck = schedule.get("stuck", False)
        paused = schedule.get("paused", False)
        disabled = function_name in disabled_functions
        if paused or deleted or disabled or org_inactive:
            is_stuck = False
        elif marked_stuck:
            # only clear the flag if we got something back. last_crawl_end is no
            # good here because a crawl that fails updates it too
            progress = schedule.get("last_page_token_update") or schedule.get(
                "latest_data"
            )
            is_stuck = (
                not progress or now() - str_to_dt(progress) > page_token_threshold
            )
        else:
            # a killed crawl re-enqueues and resets last_crawl_start; anchor on signals
            # that survive retries: token move, else last completion, else created_at.
            last_progress = (
                schedule.get("last_page_token_update")
                or schedule.get("last_crawl_end")
                or connection["created_at"]
            )
            stalled = now() - str_to_dt(last_progress) > page_token_threshold
            is_stuck = stalled and crawl_started(schedule)
        if is_stuck == marked_stuck:
            continue
        if DRY_RUN:
            logger.info(
                f"Would update stuck for connection_id: {connection_id}, function_name: {function_name}, stuck: {is_stuck}"
            )
            continue
        if is_stuck:
            resource = build_stuck_webhook_resource(connection_id, function_name)
            if not resource:
                # no resource to notify with, so don't persist stuck without a webhook
                continue
            send_schedule_stuck_webhook(
                resource,
                function_name,
                dt_to_str(now()),
                schedule.get("latest_data"),
            )
        update_crawl_items(connection_id, function_name, {"stuck": is_stuck})
        # record only after the stuck flag persists, so a failed write doesn't
        # leave an event for a transition the next run will report again
        record_event(
            connection["org_id"],
            "schedule_stuck" if is_stuck else "schedule_unstuck",
            connection["integration_name"],
            connection["integration_type"],
            connection_id=connection_id,
            customer_id=connection.get("customer_id"),
            additional_fields={"function_name": function_name},
        )


def handler(event, context):
    timeout = LAMBDA_SERVICES["stale-schedule-marker"]["timeout"] - 5
    with LambdaContextManager(event, context, timeout=timeout):
        connections = scan_connection_rows(ignore_deleted=False)
        open_sync_jobs = get_open_sync_jobs()
        active_syncs = {
            (job["connection_id"], job["function_name"]) for job in open_sync_jobs
        }
        for connection in connections:
            org_id = connection["org_id"]
            connection_id = connection["id"]
            integration_name = connection["integration_name"]
            if integration_name == "sandbox":
                continue
            integration_type = connection["integration_type"]
            deleted = connection.get("deleted", False)
            org_row = get_org_row_cached(org_id)
            # the scheduler never queues crawls for an inactive org, so like a deleted
            # connection its rows can't go stale or stuck
            org_inactive = org_row["billing_status"] in INACTIVE_BILLING_STATUSES
            # a function the org or connection deliberately turned off stops being queued,
            # so its leftover row would otherwise go stale and fire a false investigation
            disabled_functions = resolve_disabled_functions(
                connection,
                org_row,
                integration_name,
                integration_type,
            )
            try:
                integration_file = get_integration_file(
                    integration_name, integration_type
                )
                integration = integration_file.Integration()
            except PokedexException as e:
                if e.status_code == 404:
                    logger.info(f"Integration {integration_name} not found")
                    integration = None
                else:
                    raise
            connection_errors = get_connection_errors(connection_id)
            functions_with_errors = set()
            for error in connection_errors:
                for affected_endpoint in error["affected_endpoints"]:
                    endpoint = affected_endpoint["endpoint"]
                    preventing_sync = affected_endpoint.get("preventing_sync")
                    if not endpoint.startswith("GET /") or not preventing_sync:
                        continue
                    function_name = "get_" + endpoint.split("/")[-1]
                    function_name = function_name.replace("-", "_")
                    functions_with_errors.add(function_name)
            schedules = get_connection_scheduler_rows(connection_id)
            check_schedule_stuckness(
                connection, schedules, active_syncs, disabled_functions, org_inactive
            )
            for schedule in schedules:
                latest_data = schedule.get("latest_data")
                last_crawl_end = schedule.get("last_crawl_end")
                function_name = schedule["function_name"]
                if (
                    (
                        connection_id,
                        function_name,
                    )
                    in active_syncs
                ):  # don't stale check crawls that are blocked by active on-demand syncs
                    continue
                has_connection_errors = function_name in functions_with_errors
                # these won't exist on recently created rows
                marked_stale = schedule.get("stale", False)
                paused = schedule.get("paused", False)
                last_crawl_start = schedule.get("last_crawl_start")
                first_crawl_threshold = timedelta(hours=24)

                # Handle first crawl stale detection
                is_first_crawl_unfinished = (
                    last_crawl_start
                    and not first_crawl_complete(connection, schedule, function_name)
                )
                if is_first_crawl_unfinished:
                    # Determine if first crawl has exceeded threshold
                    first_crawl_is_stale = (
                        now() - str_to_dt(connection["created_at"])
                        > first_crawl_threshold
                    )

                    # Don't mark as stale if crawl is paused, deleted, disabled, org inactive, or has connection errors
                    should_ignore_staleness = (
                        paused
                        or deleted
                        or org_inactive
                        or has_connection_errors
                        or function_name in disabled_functions
                    )
                    desired_stale_state = (
                        first_crawl_is_stale and not should_ignore_staleness
                    )

                    # Update stale state if it has changed
                    if marked_stale != desired_stale_state:
                        if DRY_RUN:
                            logger.info(
                                f"Would update first_crawl items for connection_id: {connection_id}, function_name: {function_name}, stale: {desired_stale_state}"
                            )
                        else:
                            update_dict: dict[str, object] = {
                                "stale": desired_stale_state
                            }
                            if desired_stale_state == False:
                                conclude_investigation(schedule, update_dict)
                                update_dict["blocked"] = False
                            elif STAGE == "dev":
                                # dev-only: stale transitions pause the schedule so
                                # broken test integrations stop bloating scheduler rows.
                                update_dict["paused"] = True
                            update_crawl_items(
                                connection_id, function_name, update_dict
                            )
                    continue
                if not latest_data or not last_crawl_end:
                    continue
                # skip if function no longer exists in resource map (stale schedule row)
                if function_name not in function_to_resource_map.get(
                    integration_type, {}
                ):
                    logger.info(f"Skipping unknown function {function_name}")
                    continue
                latest_data_dt = str_to_dt(latest_data)
                resource = function_to_resource_map[integration_type][function_name](
                    integration
                )
                crawl_frequency = resolve_crawl_frequency(
                    connection, org_row, resource, function_name
                )
                stale_threshold = timedelta(
                    seconds=crawl_frequency * resource.stale_multiplier()
                )
                stale = now() - latest_data_dt > stale_threshold
                # shiphero we store timestampe of crawl in page_token
                # oftentimes it's not really stale bc the page_token is nearly caught up to current time
                if integration_name == "shiphero" and function_name in [
                    "get_products",
                    "get_inventory",
                    "get_orders",
                ]:
                    latest_page_token = schedule.get("latest_page_token")
                    if latest_page_token:
                        # shiphero get_inventory stores {"start": ..., "cursor": ...}; the other two store a bare timestamp
                        if isinstance(latest_page_token, dict):
                            latest_page_token = latest_page_token["start"]
                        if not latest_page_token.endswith("Z"):
                            latest_page_token += "Z"
                        latest_page_token_dt = str_to_dt(latest_page_token)
                        stale = now() - latest_page_token_dt > stale_threshold
                # a deferred schedule holds latest_data back on purpose while waiting
                # on the vendor, but only trust it while crawls keep refreshing the
                # token: a frozen token means the crawls themselves are dying
                if schedule.get("deferred"):
                    last_page_token_update = schedule.get("last_page_token_update")
                    if (
                        last_page_token_update
                        and now() - str_to_dt(last_page_token_update) <= stale_threshold
                    ):
                        stale = False
                if has_connection_errors:
                    stale = False
                if integration and not integration.is_implemented(function_name):
                    stale = False
                if deleted:
                    stale = False
                if org_inactive:
                    stale = False
                if paused:
                    stale = False
                if function_name in disabled_functions:
                    stale = False
                if stale and marked_stale:
                    # still stale, no state change — but if a code-fix PR merged and the
                    # schedule still hasn't recovered, the shipped fix didn't work:
                    # release the pointer so the next dispatch re-investigates.
                    maybe_release_investigation(schedule, connection_id, function_name)
                    continue
                if not stale and not marked_stale:
                    continue
                if DRY_RUN:
                    logger.info(
                        f"Would update crawl items for connection_id: {connection_id}, function_name: {function_name}, stale: {stale}"
                    )
                    continue
                update_dict: dict[str, object] = {"stale": stale}
                if stale == False:
                    conclude_investigation(schedule, update_dict)
                    update_dict["blocked"] = False
                elif STAGE == "dev":
                    # dev-only: stale transitions pause the schedule so broken
                    # test integrations stop bloating scheduler rows.
                    update_dict["paused"] = True
                update_crawl_items(connection_id, function_name, update_dict)

        # check sync job staleness
        check_sync_job_staleness(open_sync_jobs)

        # check sync job stuckness
        check_sync_job_stuckness(open_sync_jobs)

        return {"status": "success", "message": "stale marker completed"}

